mapper.select:
SELECT NVL(SUM(r.register_revenue), 0) AS registerRevenue, NVL(SUM(r.medical_revenue), 0) AS medicalRevenue, NVL(SUM(r.register_revenue), 0) + NVL(SUM(r.medical_revenue), 0) + NVL(SUM(r.service_revenue), 0) AS outpatientRevenue, NVL(SUM(r.service_revenue), 0) AS serviceRevenue FROM TR_REV_OV r INNER JOIN TR_DEPT_DICT d ON r.dept_code = d.dept_code WHERE r.stat_date BETWEEN #{startDate} AND #{endDate} AND d.outp_or_inp IN (0, 2)
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
